    { id: 'e4', title: "EVENT 4" },
    { id: 'e5', title: "EVENT 5" },
    { id: 'e6', title: "EVENT 6" },
    { id: 'e7', title: "EVENT 7" }
]

export default function EventsPage() {
    console.log("events")
    return (
        <ul>
            {DummyEvents.map((event) => {
                <li key={event.id}>{event.title}</li>
            })}
        </ul>
    )
}
